head.script:
scwin.onpageload = function() {
    var arr = ["test1","t1","","test2","t2","","test3-f","t3","false","aaa1","a1","","aaa2","a2","","bbb1","b1","","bbb2","b2",""];
    dataList1.setData(arr);	
};

scwin.testFn = function(keyStr){
	var jsonData = [{"col1":"붕어빵9", "col2":"붕어빵9"},
        {"col1":"새우빵9", "col2":"새우빵9"},
        {"col1":"이상빵9", "col2":"이상빵9"}];

    if (keyStr == "붕어빵9") {
       dataList2.setJSON([{"col1":"붕어빵9", "col2":"붕어빵9"}]);
    } else if (keyStr == "새우빵9") {
        dataList2.setJSON([{"col1":"새우빵9", "col2":"새우빵9"}]);
    } else if (keyStr == "이상빵9") {
        dataList2.setJSON([{"col1":"이상빵9", "col2":"이상빵9"}]);
    } else {
        dataList2.setJSON(jsonData);
    }

    autoComplete2.setItemSet( "data:dataList2" ,"col1" , "col2" );
    autoComplete2.openTable(); 

}

	scwin.checkVal = function() {
		return document.getElementsByTagName('table').length == 0;
	}
	scwin.unitTest = function() {
		//init
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		//Run  and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest()
